use font_generator::renderer::{Rasterization, RenderPipeline, RendererRole};
use font_generator::stem_fitting::StemFittingStrategy;
use font_generator::surface::{
    render_text_with_pipeline, render_text_with_renderer, HAlign, RenderedText,
    TextRenderRequest, WrapMode,
};
use font_generator::{generate, Config, Hinting, MetricRounding, MissingGlyphs};
use std::collections::BTreeMap;
use std::fs;
use std::io::Write;

const WIDTH: u32 = 1200;
const HEIGHT: u32 = 176;
const ORIGIN_X: u32 = 16;
const BASELINES: [u32; 3] = [40, 88, 136];
const SIZES: [f32; 3] = [16.0, 20.0, 32.0];

fn base_config(size_px: f32, hinting: Hinting) -> Config {
    Config {
        size_px,
        axes: BTreeMap::new(),
        hinting,
        output_bits: 1,
        mono_threshold: 128,
        gray_gamma: 1.0,
        characters: String::new(),
        missing_glyphs: MissingGlyphs::Error,
        kerning: false,
        metric_rounding: MetricRounding::Subpixel,
        mono_raster: Default::default(),
    }
}

fn line_request(config: Config, text: &str, width: u32, height: u32) -> TextRenderRequest {
    TextRenderRequest {
        config,
        text: text.to_string(),
        width,
        height,
        wrap: WrapMode::Clip,
        align: HAlign::Left,
        foreground: [0, 0, 0, 255],
        background: [255, 255, 255, 255],
        palette: None,
    }
}

fn is_ink(px: &[u8]) -> bool {
    px[0] < 128 || px[1] < 128 || px[2] < 128
}

fn check_no_edge_ink(rendered: &RenderedText, label: &str) {
    let w = rendered.width as usize;
    let h = rendered.height as usize;
    let edge_ink = |x: usize, y: usize| is_ink(&rendered.pixels[(y * w + x) * 4..(y * w + x) * 4 + 3]);
    for x in 0..w {
        if edge_ink(x, 0) || edge_ink(x, h - 1) {
            panic!("clipped ink at top/bottom edge in {}", label);
        }
    }
    for y in 0..h {
        if edge_ink(0, y) || edge_ink(w - 1, y) {
            panic!("clipped ink at left/right edge in {}", label);
        }
    }
}

fn render_line_preview(font: &[u8], req: &TextRenderRequest) -> RenderedText {
    let pipeline = RenderPipeline {
        fitting: StemFittingStrategy::FontHintsAuto,
        rasterization: Rasterization::FreeTypeMonoTerminals,
        diagonal_fitting: true,
    };
    let first = render_text_with_pipeline(font, req, pipeline).unwrap_or_else(|e| {
        panic!("preview render failed for {:?}: {}", req.text, e);
    });
    let second = render_text_with_pipeline(font, req, pipeline).unwrap_or_else(|e| {
        panic!("preview re-render failed for {:?}: {}", req.text, e);
    });
    if first.pixels != second.pixels {
        panic!("nondeterministic preview render for {:?}", req.text);
    }
    first
}

fn render_line_baseline(font: &[u8], req: &TextRenderRequest) -> RenderedText {
    let first = render_text_with_renderer(font, req, RendererRole::Baseline).unwrap_or_else(|e| {
        panic!("baseline render failed for {:?}: {}", req.text, e);
    });
    let second = render_text_with_renderer(font, req, RendererRole::Baseline).unwrap_or_else(|e| {
        panic!("baseline re-render failed for {:?}: {}", req.text, e);
    });
    if first.pixels != second.pixels {
        panic!("nondeterministic baseline render for {:?}", req.text);
    }
    first
}

fn write_gray_png(path: &str, gray: &[u8], width: u32, height: u32) {
